def update(self, **kwargs):
    """
    Update all elements in the current QuerySet, setting all the given
    fields to the appropriate values.
    """
    self._not_support_combined_queries("update")
    if self.query.is_sliced:
        raise TypeError("Cannot update a query once a slice has been taken.")
    self._for_write = True
    query = self.query.chain(sql.UpdateQuery)

    # Resolve expressions in update values
    resolved_values = {}
    for key, value in kwargs.items():
        if hasattr(value, 'resolve_expression'):
            resolved_value = value.resolve_expression(query=query, allow_joins=False, for_save=True)
            resolved_values[key] = resolved_value
        else:
            resolved_values[key] = value

    query.add_update_values(resolved_values)

    # Inline annotations in order_by(), if possible.
    new_order_by = []
    for col in query.order_by:
        alias = col
        descending = False
        if isinstance(alias, str) and alias.startswith("-"):
            alias = alias[1:]
            descending = True
        if alias in query.annotations:
            annotation = query.annotations[alias]
            if getattr(annotation, "contains_aggregate", False):
                raise exceptions.FieldError(
                    f"Cannot update when ordering by an aggregate: {alias}"
                )
            resolved = annotation.resolve_expression(
                query=query, allow_joins=False, for_save=False
            )
            if descending:
                resolved = resolved.desc()
            new_order_by.append(resolved)
        else:
            new_order_by.append(col)
    query.order_by = tuple(new_order_by)

    # Clear any annotations so that they won't be present in subqueries.
    query.annotations = {}

    with transaction.mark_for_rollback_on_error(using=self.db):
        rows = query.get_compiler(self.db).execute_sql(ROW_COUNT)
    self._result_cache = None
    return rows
